//! Parity tests against the Go original (`github.com/junhinhow/charm-layout`).
//!
//! The golden file is generated by the Go program in
//! `reference/go/charm-layout/cmd/parity`, which exercises the same public
//! API in the same order.

use charm_layout::{Direction, Flex, Grid};
use charm_parity::assert_golden;

/// Small helper that mirrors the `saida` builder of the Go parity program.
struct Output(String);

impl Output {
    fn section(&mut self, name: &str) {
        self.0.push_str("=== ");
        self.0.push_str(name);
        self.0.push_str(" ===\n");
    }

    fn block(&mut self, content: &str) {
        self.0.push_str(content);
        self.0.push('\n');
    }
}

/// Builds the very same output as the Go parity program.
#[allow(clippy::too_many_lines)]
fn build_output() -> String {
    let mut out = Output(String::new());

    out.section("flex row com gap");
    out.block(
        &Flex::new(Direction::Row)
            .set_size(40, 6)
            .set_gap(2)
            .add_child(0.3, "Sidebar")
            .add_child(0.7, "Main")
            .render(),
    );

    out.section("flex row sem gap");
    out.block(
        &Flex::new(Direction::Row)
            .set_size(40, 4)
            .add_child(0.5, "Esquerda")
            .add_child(0.5, "Direita")
            .render(),
    );

    out.section("flex column com gap");
    out.block(
        &Flex::new(Direction::Column)
            .set_size(30, 12)
            .set_gap(1)
            .add_child(0.2, "Header")
            .add_child(0.6, "Body")
            .add_child(0.2, "Footer")
            .render(),
    );

    out.section("flex column sem gap");
    out.block(
        &Flex::new(Direction::Column)
            .set_size(30, 6)
            .add_child(0.5, "Topo")
            .add_child(0.5, "Base")
            .render(),
    );

    out.section("flex ratio zero");
    out.block(
        &Flex::new(Direction::Row)
            .set_size(20, 3)
            .add_child(0.0, "Zero")
            .add_child(1.0, "Full")
            .render(),
    );

    out.section("flex ratios diferentes de um");
    out.block(
        &Flex::new(Direction::Row)
            .set_size(40, 3)
            .add_child(0.25, "A")
            .add_child(0.25, "B")
            .add_child(0.25, "C")
            .render(),
    );

    out.section("flex gap maior que a largura");
    out.block(
        &Flex::new(Direction::Row)
            .set_size(4, 3)
            .set_gap(5)
            .add_child(0.5, "A")
            .add_child(0.5, "B")
            .render(),
    );

    out.section("flex vazio");
    out.block(&Flex::new(Direction::Row).render());

    out.section("flex razao invalida tolerante");
    out.block(
        &Flex::new(Direction::Row)
            .set_size(20, 2)
            .add_child(-0.5, "A")
            .add_child(1.0, "B")
            .render(),
    );

    out.section("flex soma de razoes zero tolerante");
    out.block(
        &Flex::new(Direction::Row)
            .set_size(20, 2)
            .add_child(0.0, "A")
            .add_child(0.0, "B")
            .render(),
    );

    out.section("flex tamanho negativo tolerante");
    out.block(
        &Flex::new(Direction::Row)
            .set_size(-10, 2)
            .add_child(0.5, "A")
            .render(),
    );

    out.section("grid tres colunas cinco filhos com gap");
    out.block(
        &Grid::new(3)
            .set_size(60, 9)
            .set_gap(1)
            .add_children(["Cell 1", "Cell 2", "Cell 3", "Cell 4", "Cell 5"])
            .render(),
    );

    out.section("grid tres colunas cinco filhos sem gap");
    out.block(
        &Grid::new(3)
            .set_size(60, 6)
            .add_children(["Cell 1", "Cell 2", "Cell 3", "Cell 4", "Cell 5"])
            .render(),
    );

    out.section("grid numero impar de filhos");
    out.block(
        &Grid::new(2)
            .set_size(30, 6)
            .add_children(["A", "B", "C"])
            .render(),
    );

    out.section("grid zero colunas");
    out.block(
        &Grid::new(0)
            .set_size(20, 4)
            .add_children(["A", "B"])
            .render(),
    );

    out.section("grid vazio");
    out.block(&Grid::new(3).render());

    out.section("grid gap maior que o espaco");
    out.block(
        &Grid::new(10)
            .set_size(80, 10)
            .set_gap(10)
            .add_children(["A", "B", "C", "D", "E", "F", "G", "H", "I", "J"])
            .render(),
    );

    out.0
}

#[test]
fn layout_matches_the_go_original() {
    assert_golden("layout", &build_output());
}
